package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime;
@Document(collection="stock_movements") public class StockMovement { @Id private String id; private String productId; private String warehouseId; private StockMovementType type; private int quantity; private int balanceAfter; private String referenceId; private String reason; private LocalDateTime createdAt=LocalDateTime.now(); public StockMovement(){} public String getId(){return id;} public void setId(String v){id=v;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public StockMovementType getType(){return type;} public void setType(StockMovementType v){type=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public int getBalanceAfter(){return balanceAfter;} public void setBalanceAfter(int v){balanceAfter=v;} public String getReferenceId(){return referenceId;} public void setReferenceId(String v){referenceId=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
